// Extract LLM category response + bring back the original candidate id
const raw = $input.item.json.choices[0].message.content;
const category = raw.trim().toLowerCase().replace(/[^a-z-]/g, '');

// Reference the original SQLite row for this same item
const id = $('Get All Candidates').item.json.id;
const name = $('Get All Candidates').item.json.full_name;

console.log(`[${id}] ${name} → ${category}`);

return {
  json: {
    id: id,
    full_name: name,
    skill_category: category
  }
};
